-- ============================================================================
-- BHA location hierarchy seed: Ethiopia (ET)
-- Source: "Africa Location Hierarchies - Universal Review" - Ethiopia
-- 844 locations beyond the country root. Idempotent: re-running refreshes.
-- Prerequisite: supabase/migrations/004_location_hierarchy.sql
-- ============================================================================

-- 0. Country row (adds any territory missing from the base schema seed)
insert into public.countries (code, name) values
  ('ET', 'Ethiopia')
on conflict (code) do update set name = excluded.name;

-- 1. Country root (level 1)
insert into public.locations (country_code, parent_id, name, location_type, level, path, sort_order)
select 'ET', null, 'Ethiopia', 'Country', 1, 'ethiopia', 0
on conflict (country_code, path) do update set
  name = excluded.name, location_type = excluded.location_type, level = excluded.level;

-- 2. Level 2 (14 rows)
insert into public.locations (country_code, parent_id, name, location_type, level, path, sort_order)
select 'ET', p.id, v.name, v.location_type, v.level, v.path, v.sort_order
from (values
    ('ethiopia', 'Addis Ababa Chartered City', 'Chartered City', 2, 'ethiopia/addis-ababa-chartered-city', 0),
    ('ethiopia', 'Afar Region', 'Regional State', 2, 'ethiopia/afar-region', 1),
    ('ethiopia', 'Amhara Region', 'Regional State', 2, 'ethiopia/amhara-region', 2),
